    11→use x_oracle::price_feed::{Self, PriceFeedComponent};
    12→
    13→const U8_MAX: u64 = 255;
    14→const CONF_TOLERANCE_DENOMINATOR: u64 = 10_000;
    15→// A global static pyth price feed delay allowed.
    16→const PRICE_FEED_DELAY_SECONDS: u64 = 30;
    17→
    18→public struct PythFeedData has drop, store {
    19→    feed: ID,
    20→    spot_confidence_tolerance_bps: u64,
    21→    ema_confidence_tolerance_bps: u64,
    22→}
    23→
    24→public(package) fun get_pyth_price(
    25→    pyth_price_info_object: &PriceInfoObject,
    26→    pyth_feed_data: &PythFeedData,
    27→    clock: &Clock,
    28→): (PriceFeedComponent, PriceFeedComponent) {
    29→    let pyth_price_feed = pyth_price_info_object.get_price_info_from_price_info_object().get_price_feed();
    30→
    31→    let ema_price = pyth_price_feed.get_ema_price();
    32→    let spot_price = pyth_price_feed.get_price();
    33→
    34→    let (ema_price_value, ema_price_decimals, ema_update_time) = ensure_price_ok(&ema_price, pyth_feed_data.ema_confidence_tolerance_bps, clock);
    35→    let (spot_price_value, spot_price_decimals, spot_update_time) = ensure_price_ok(&spot_price, pyth_feed_data.spot_confidence_tolerance_bps, clock);
    36→
    37→    assert!(ema_price_decimals == spot_price_decimals, oracle_error::pyth_spot_ema_price_decimals_not_match());
    38→
    39→    let ema_price_value = normalize_decimals(ema_price_value, ema_price_decimals);
    40→    let spot_price_value = normalize_decimals(spot_price_value, ema_price_decimals);
    41→
    42→    (
    43→        price_feed::new_component(ema_price_value, ema_update_time),
    44→        price_feed::new_component(spot_price_value, spot_update_time),
    45→    )
    46→}
    47→
    48→/// Perform confidence and staleness check on the price, returns the price value and decimal
    49→fun ensure_price_ok(price: &Price, conf_tolerance: u64, clock: &Clock): (u64, u8, u64) {
    50→    let price_value = price.get_price();
    51→    let price_value = price_value.get_magnitude_if_positive();
    52→
    53→    let price_decimals = price.get_expo();
    54→    let price_decimals = price_decimals.get_magnitude_if_negative();
    55→
    56→    let price_conf = price.get_conf();
    57→
    58→    // For price value, the decimals could definitely fit in a u8, otherwise there's a bug
    59→    assert!(price_decimals <= U8_MAX, oracle_error::pyth_price_decimals_too_large());
    60→    assert_price_conf_within_range(price_value, price_conf, conf_tolerance);
    61→
    62→    let update_time = assert_price_not_stale(price, clock);
    63→
    64→    (price_value, price_decimals as u8, update_time)
    65→}
    66→
    67→fun normalize_decimals(price_value: u64, price_decimals: u8): u64 {
    68→    let formatted_decimals = price_feed::decimals();
    69→
    70→    let price_value_with_formatted_decimals = if (price_decimals < formatted_decimals) {
    71→        price_value * pow10_u64(formatted_decimals - price_decimals)
    72→    } else {
    73→        // This should rarely happen, since formatted_decimals is 9 and price_decimals is usually smaller than 8
    74→        price_value / pow10_u64(price_decimals - formatted_decimals)
    75→    };
    76→    assert!(price_value_with_formatted_decimals > 0, oracle_error::pyth_price_decimals_too_large());
    77→
    78→    price_value_with_formatted_decimals
    79→}
    80→
    81→fun assert_price_not_stale(price: &Price, clock: &Clock): u64 {
    82→    let price_updated_time = price::get_timestamp(price);
    83→    let now = clock::timestamp_ms(clock) / 1000;
    84→    // Make sure price is updated within PRICE_FEED_DELAY_SECONDS
    85→    assert!(price_updated_time >= now - PRICE_FEED_DELAY_SECONDS, oracle_error::pyth_price_too_old());
    86→    assert!(price_updated_time <= now , oracle_error::future_pyth_price());
    87→
    88→    price_updated_time
    89→}
    90→
    91→fun assert_price_conf_within_range(price_value: u64, price_conf: u64, price_conf_tolerance: u64) {
    92→    // Check price confidence is within range
    93→    let price_conf_range = price_conf_tolerance * 100; // multiply by 100, to make it in percentage format
    94→    let price_conf_diff = (price_conf * CONF_TOLERANCE_DENOMINATOR * 100 as u128) / (price_value as u128);
    95→    assert!((price_conf_diff as u64) <= price_conf_range, oracle_error::pyth_price_conf_too_large());
    96→}
    97→
    98→public(package) fun assert_pyth_price_info_object(
    99→    self: &PythFeedData,
   100→    price_info_object: &PriceInfoObject,
