  1128→/// Calculates the debts in usd against latest oracle ema price, without including the borrow weights
  1129→fun debts_value_usd_for_liquidation<MarketType>(
  1130→    emode_group: &EModeGroup,
  1131→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1132→
  1133→    obligation: &Obligation<MarketType>,
  1134→
  1135→    coin_decimals_registry: &CoinDecimalsRegistry,
  1136→
  1137→    x_oracle: &XOracle,
  1138→    clock: &Clock,
  1139→): (Decimal, Decimal) {
  1140→    let mut total_weighted_value_usd = float::zero();
  1141→    let mut total_value_usd = float::zero();
  1142→
  1143→    let debt_types = obligation.debt_types();
  1144→    let (mut i, n) = (0, debt_types.length());
  1145→
  1146→    let oracle_base_token = emode_group.get_oracle_base_token();
  1147→
  1148→    while (i < n) {
  1149→        let debt_type = *debt_types.borrow(i);
  1150→
  1151→        let reserve = reserves.load_by_type(debt_type);
  1152→
  1153→        let debt_amount = obligation.debt(debt_type).debt(reserve.borrow_index().value());
  1154→        let decimals = coin_decimals_registry.decimals(debt_type);
  1155→        let coin_price = get_price(x_oracle, debt_type, oracle_base_token, clock);
  1156→
  1157→        let coin_value_usd = coin_value(coin_price, debt_amount, decimals);
  1158→        total_value_usd = total_value_usd.add(coin_value_usd);
